import math
def control(obs):
 h=obs['hitch_deg']; cam=obs['views'].get('camera'); steer=1.6*h
 if cam:
  origin=cam['origin']; rear=obs['rig']['trailer_rear']; a=math.radians(h)
  pts=[]
  for b,d in cam['walls']:
   b=math.radians(b); x=origin[0]+d*math.cos(b)-rear[0]; y=origin[1]+d*math.sin(b)-rear[1]
   s=-x*math.cos(a)+y*math.sin(a); z=x*math.sin(a)+y*math.cos(a)
   if s>0: pts.append((s,z))
  centers=[]
  for s0 in [2.5,3.5,4.5,5.5]:
   left=[z for s,z in pts if abs(s-s0)<0.8 and z>0.3]; right=[z for s,z in pts if abs(s-s0)<0.8 and z<-.3]
   if left and right:
    z=(min(left)+max(right))/2; centers.append((s0,z))
  if centers:
   s,z=min(centers,key=lambda p:abs(p[0]-4)); err=math.degrees(math.atan2(z,s)); steer=.75*h-2.3*err
 return (max(-30,min(30,steer)),-0.7,-23)

