import math
def control(obs):
 h=obs['hitch_deg']; cam=obs['views'].get('camera'); steer=1.8*h
 if cam:
  origin=cam['origin']; rear=obs['rig']['trailer_rear']; a=math.radians(h)
  def point(b,d):
   b=math.radians(b); x=origin[0]+d*math.cos(b)-rear[0]; y=origin[1]+d*math.sin(b)-rear[1]
   return (-x*math.cos(a)+y*math.sin(a),x*math.sin(a)+y*math.cos(a))
  corners=[point(b,d) for b,d in cam.get('target_corners',[])]
  if len(corners)>=4:
   s=sum(p[0] for p in corners)/len(corners); z=sum(p[1] for p in corners)/len(corners)
   steer=1.8*h-2.4*math.degrees(math.atan2(z,max(2,s)))
  else:
   pts=[point(b,d) for b,d in cam['walls']]
   left=sorted([(s,z) for s,z in pts if s>0 and z>.3],key=lambda p:abs(p[0]-3.5))[:3]
   right=sorted([(s,z) for s,z in pts if s>0 and z<-.3],key=lambda p:abs(p[0]-3.5))[:3]
   if left and right:
    z=(sum(p[1] for p in left)/len(left)+sum(p[1] for p in right)/len(right))/2
    steer=1.8*h-2.4*math.degrees(math.atan2(z,3.5))
 return (max(-32,min(32,steer)),-0.5,-23)

